import{_ as e,o,c as a,a2 as r}from"./chunks/framework.Crpw6aS5.js";const n=JSON.parse('{"title":"1960年 · 桑伯恩地图的控股艺术","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/1960年.md","filePath":"05_quotes/by-year/1960年.md"}'),l={name:"05_quotes/by-year/1960年.md"};function u(q,t,s,_,c,h){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="_1960年-·-桑伯恩地图的控股艺术" tabindex="-1">1960年 · 桑伯恩地图的控股艺术 <a class="header-anchor" href="#_1960年-·-桑伯恩地图的控股艺术" aria-label="Permalink to &quot;1960年 · 桑伯恩地图的控股艺术&quot;">​</a></h1><blockquote><p>&quot;如果我们下跌15%而平均指数下跌30%的年份，比我们和平均指数都上涨20%的年份要好得多。&quot;——巴菲特（30岁）</p></blockquote><p>本页收录1960年致股东信中的经典语录。这一年，巴菲特详细披露了桑伯恩地图公司的经典控股案例——以45美元买入内在价值约110美元的公司，用&quot;价值实现&quot;而非股价波动来衡量投资成败。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>&quot;如果我们下跌15%而平均指数下跌30%的年份，比我们和平均指数都上涨20%的年份要好得多。&quot;</p></blockquote><blockquote><p>&quot;在任何年份，我们相对于平均指数表现出的任何优异表现，可能不是在上升市场中取得的，而是在平稳或下降市场中。&quot;</p></blockquote><blockquote><p>&quot;我们的基本业务是购买被低估的证券，在低估被纠正时卖出，以及投资于利润依赖于公司而非市场行为的特殊情形。&quot;</p></blockquote><blockquote><p>&quot;这种控制情况很少发生。然而，它确实说明了在短期内（如一年内）衡量我们结果的无效性。&quot;</p></blockquote><blockquote><p>&quot;未经合伙人一致同意，不会做任何事情。&quot;</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>1960年道指下跌6.3%，而合伙企业取得22.8%的正收益，再度跑赢大盘。巴菲特在这一年详细讲述了桑伯恩地图公司案例：通过公开市场持续买入成为大股东，最终通过资产分离计划让希望退出的股东以公平价值退出，实现了账面价值基础上的大幅提升。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><p><a href="/01_letters/1960年/翻译.html">01_letters/1960年/翻译</a> · <a href="/01_letters/1960年/核心总结.html">01_letters/1960年/核心总结</a> · <a href="/01_letters/1960年/思维导图.html">01_letters/1960年/思维导图</a></p>',16)])])}const i=e(l,[["render",u]]);export{n as __pageData,i as default};
